class Solution {
public:
    long long maxProduct(string s) {
        int n = s.size();
        vector<int> rad(n), left(n, 0), right(n, 0);
        for (int i = 0, l = 0, r = -1; i < n; ++i) {
            int k = i > r ? 1 : min(rad[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) ++k;
            rad[i] = k;
            if (i + k - 1 > r) { l = i - k + 1; r = i + k - 1; }
            int len = 2 * k - 1;
            left[i + k - 1] = max(left[i + k - 1], len);
            right[i - k + 1] = max(right[i - k + 1], len);
        }
        for (int i = n - 2; i >= 0; --i)
            left[i] = max(left[i], left[i + 1] - 2);
        for (int i = 1; i < n; ++i)
            left[i] = max(left[i], left[i - 1]);
        for (int i = 1; i < n; ++i)
            right[i] = max(right[i], right[i - 1] - 2);
        for (int i = n - 2; i >= 0; --i)
            right[i] = max(right[i], right[i + 1]);
        long long ans = 0;
        for (int i = 0; i + 1 < n; ++i)
            ans = max(ans, 1LL * left[i] * right[i + 1]);
        return ans;
    }
};
